import {interestTaxQuote,annualInterestRows,canEnableInterestTax} from './interest-tax.js';
export function renderInterestTax(s,gross,{won,escape:e}){const q=interestTaxQuote(s,gross);return `<details class="finance-help"><summary>예금 이자 · 공제와 실수령 장부</summary><p>${s.interestTax?'일반과세 거주자 예금 이자 모형 · 세율 자료 연결':'기존 공제 모형 유지 · 과거 장부 소급 없음'}</p><dl class="credit-summary"><div>현재 조건의 월 세전 이자 <b>${won(q.gross)}</b></div><div>${s.interestTax?'소득세':'기존 일괄 공제'} <b>${won(s.interestTax?q.national:q.total)}</b></div>${s.interestTax?`<div>지방세 <b>${won(q.local)}</b></div>`:''}<div>월 실수령 예상 <b>${won(q.net)}</b></div></dl><p>현재 잔액·금리 기준의 예상입니다. 다음 달 시장과 잔액에 따라 달라집니다.</p>${s.interestTax?`<p>연결 시점 ${e(s.interestTax.activatedMonth)}. 다음 월부터 기록합니다.</p>${annualInterestRows(s).map(y=>`<p><b>${e(y.year)}년 · 월 지급 기록 ${y.months}개월${y.termSettlements?` · 계약 정산 ${y.termSettlements}건`:``}${y.months<12?' · 일부 기간':''}</b><br>세전 ${won(y.gross)}<br>공제 ${won(y.total)}<br>실수령 ${won(y.net)}</p>`).join('')||'<p>아직 진행한 월의 기록이 없습니다.</p>'}`:`<button class="btn secondary small" data-interest-tax-review="yes" ${canEnableInterestTax(s)?'':'disabled'}>공제 방식 확인 후 연결</button>`}<p>2002~2004년 소득세 15%·지방세 1.5%, 2005년 이후 14%·1.4%의 기본 세율을 참고합니다. 변동금리 잔액은 월 발생 즉시 지급합니다. 계약형 예금은 발생 시기별 기본 세율을 묶어 지급 때 공제하는 교육용 모형입니다. 2026년 10월 이후에는 같은 세율을 유지하는 가상 규칙입니다.</p><p>각 공제는 원 미만 버림으로 단순화합니다. 실제 은행의 끝수 처리·소액 징수·비과세·세금우대·ISA·비거주자·상품별 귀속 시기·실제 상품 만기·중도해지 조건은 미반영이며 계약형 기능은 별도 교육용 모형입니다. 원천징수는 최종 세금 정산이 아닙니다. 금융소득 종합과세·추가 납부액은 계산하지 않으며 이 장부는 월 지급 이자와 계약 정산 이자만 집계합니다. 계약 이자는 지급 연도에 기록하며 실제 귀속연도 판정은 아닙니다.</p><p><a href="https://www.nabo.go.kr/board/file/down.do?fid=13294" target="_blank" rel="noopener noreferrer">국회예산정책처 · 2016 조세 통계편 23쪽 ↗</a><br><a href="https://taxlaw.nts.go.kr/qt/USEQTA002P.do?ntstDcmId=010000000000117900" target="_blank" rel="noopener noreferrer">국세청 · 발생 시기별 이자 세율 ↗</a><br><a href="https://www.law.go.kr/lsLinkCommonInfo.do?chrClsCd=010202&lsJoLnkSeq=1029492161" target="_blank" rel="noopener noreferrer">지방세법 · 특별징수 ↗</a></p></details>`;}
